#!/usr/bin/env sh
set -eu

config="${XDG_CONFIG_HOME:-$HOME/.config}/opencode"
dest="$config/plugins/usage-limits"
mkdir -p "$dest"

decode() {
  if command -v base64 >/dev/null 2>&1; then
    if base64 --decode </dev/null >/dev/null 2>&1; then
      base64 --decode
    else
      base64 -D
    fi
  else
    openssl base64 -d
  fi
}

decode > "$dest/package.json" <<'B64'

B64

decode > "$dest/index.ts" <<'B64'

B64

decode > "$dest/gui-experimental.cjs" <<'B64'

B64

decode > "$dest/README.md" <<'B64'

B64

printf '\nOpenCode Usage Limits installed:\n  %s\n\n' "$dest"
printf 'Restart OpenCode or run: opencode reload\n'
printf 'Then open a session. The pill appears at the bottom of the left sidebar.\n\n'